package dev.zyon;
import java.io.IOException;
import net.minecraft.client.gui.*;
import org.lwjgl.input.Keyboard;
public final class KeyLayoutEditor extends GuiScreen {
 private final Zyon client;private final GuiScreen parent;private int chosen=-1,drag=-1,dx,dy;private boolean awaiting;private int left,top;private float canvasScale;private String status="";
 public KeyLayoutEditor(Zyon c,GuiScreen p){client=c;parent=p;}private Feature f(){return client.feature("keystrokes");}
 public void initGui(){canvasScale=Math.max(.1f,Math.min(1,Math.min((width-32f)/240,(height-105f)/240)));left=(int)(width/2-110*canvasScale);top=55;buttonList.clear();buttonList.add(new GuiButton(0,width/2-150,height-29,96,20,"Adicionar tecla"));buttonList.add(new GuiButton(1,width/2-50,height-29,96,20,"Remover tecla"));buttonList.add(new GuiButton(2,width/2+50,height-29,96,20,"Restaurar"));buttonList.add(new GuiButton(3,width-69,8,60,20,"Concluir"));}
 public void drawScreen(int x,int y,float p){drawRect(0,0,width,height,0xEE101522);drawCenteredString(fontRendererObj,"LAYOUT DAS TECLAS",width/2,12,client.accent());drawCenteredString(fontRendererObj,awaiting?"Pressione a tecla desejada / Esc cancela":"Arraste para mover. Clique duas vezes para trocar a tecla.",width/2,29,0xFFC5D3E7);net.minecraft.client.renderer.GlStateManager.pushMatrix();net.minecraft.client.renderer.GlStateManager.translate(left,top,0);net.minecraft.client.renderer.GlStateManager.scale(canvasScale,canvasScale,1);Ui.box(-10,-10,240,240,5,0xFF1E2636);drawRect(110,0,111,220,0x55335577);drawRect(0,110,220,111,0x55335577);for(int i=0;i<8;i++)if(f().flag("_key"+i)){int xx=client.keystrokes.keyX(i),yy=client.keystrokes.keyY(i);if(chosen==i)Ui.box(xx-3,yy-3,client.keystrokes.keyWidth(i)+6,client.keystrokes.keyHeight(i)+6,4,client.accent());client.keystrokes.drawKey(i,xx,yy,true);}net.minecraft.client.renderer.GlStateManager.popMatrix();drawCenteredString(fontRendererObj,status,width/2,height-43,0xFFFFCD7D);super.drawScreen(x,y,p);}
 protected void actionPerformed(GuiButton b){if(b.id==0){int free=-1;for(int i=0;i<8;i++)if(!f().flag("_key"+i)){free=i;break;}if(free<0){status="Limite de 8 teclas. Remova uma para adicionar outra.";return;}chosen=free;awaiting=true;status="";}if(b.id==1&&chosen>=0){f().setting("_key"+chosen).set(0);chosen=-1;}if(b.id==2){client.keystrokes.resetKeys();status="Layout padrao restaurado.";}if(b.id==3)mc.displayGuiScreen(parent);client.profiles.saveAutomatic();}
 protected void mouseClicked(int x,int y,int b)throws IOException{if(awaiting){if(y<height-40&&y>45){f().setting("_key"+chosen).set(1);f().setting("_code"+chosen).set(b-100);awaiting=false;client.profiles.saveAutomatic();}return;}for(GuiButton button:buttonList)if(button.mousePressed(mc,x,y)){super.mouseClicked(x,y,b);return;}x=(int)((x-left)/canvasScale);y=(int)((y-top)/canvasScale);if(b==0)for(int i=7;i>=0;i--)if(f().flag("_key"+i)&&Ui.hit(x,y,client.keystrokes.keyX(i),client.keystrokes.keyY(i),client.keystrokes.keyWidth(i),client.keystrokes.keyHeight(i))){if(chosen==i&&System.currentTimeMillis()-lastClick<300){awaiting=true;drag=-1;}else{chosen=drag=i;dx=x-client.keystrokes.keyX(i);dy=y-client.keystrokes.keyY(i);}lastClick=System.currentTimeMillis();return;}}
 private long lastClick;
 protected void mouseClickMove(int x,int y,int b,long t){if(drag>=0){f().setting("_kx"+drag).set((x-left)/canvasScale-dx);f().setting("_ky"+drag).set((y-top)/canvasScale-dy);}}
 protected void mouseReleased(int x,int y,int b){drag=-1;client.profiles.saveAutomatic();}
 protected void keyTyped(char c,int key)throws IOException{if(awaiting){if(key!=Keyboard.KEY_ESCAPE){f().setting("_key"+chosen).set(1);f().setting("_code"+chosen).set(key);client.profiles.saveAutomatic();}awaiting=false;return;}if(key==Keyboard.KEY_ESCAPE)mc.displayGuiScreen(parent);}
 public void onGuiClosed(){client.profiles.saveAutomatic();}public boolean doesGuiPauseGame(){return false;}
}
